        "py": "“Dāngrán shì wǒ dāng jiā le,” péngyou jiāo'ào de huídá, “wǒmen jiā yǒu yí ge guīdìng, xiǎoshì yóu qīzi juédìng, dàshì dōu yóu wǒ zuò zhǔ.”",
        "vi": "“Tất nhiên là tôi làm chủ rồi,” anh bạn kiêu hãnh đáp, “nhà tôi có một quy định: việc nhỏ do vợ quyết định, còn việc lớn đều do tôi làm chủ.”"
