        "py": "“Xiǎoshì jiù shì jiā li de jīngjì wèntí, bǐrú gāi mǎi shénme, gāi zuò shénme děngděng. Dàshì kě jiù duō le, bǐrú shéi dāng Měiguó xià jiè zǒngtǒng, Zhōngguó shénme shíhou néng dào yuèqiú shang qù, rénlèi zěnme bān dào Huǒxīng shang qù zhù děngděng, zhèxiē dàshì dōu yóu wǒ kǎolǜ.”",
