        "vi": "Một gia đình ba người dọn vào nhà mới. Người vợ thấy chồng và con trai không mấy chú ý vệ sinh, thường làm nhà cửa bừa bộn, bèn viết một biểu ngữ trong nhà: “Giữ vệ sinh, ai cũng có trách nhiệm” để nhắc chồng con giữ vệ sinh."
