        "py": "Fùzérén kànjiàn xiūlǐgōng, jiù shuō: “Zhème kuài jiù xiūhǎo le?” Xiūlǐgōng shuō: “Bú shì, wǒ qù le tāmen jiā, kěshì zài ménkǒu àn le bàntiān ménlíng, yě méiyǒu rén chūlai kāi mén, suǒyǐ wǒ zhǐhǎo huílai le.”",
