        "zh": "新学年开始，我们高年级学生去车站迎接新同学。我见一个漂亮的小女生站在一个大箱子旁不知所措，便主动上前帮她扛箱子。",
        "py": "Xīn xuénián kāishǐ, wǒmen gāo niánjí xuésheng qù chēzhàn yíngjiē xīn tóngxué. Wǒ jiàn yí ge piàoliang de xiǎo nǚshēng zhàn zài yí ge dà xiāngzi páng bù zhī suǒ cuò, biàn zhǔdòng shàngqián bāng tā káng xiāngzi.",
        "vi": "Đầu năm học mới, sinh viên khóa trên chúng tôi ra ga đón sinh viên mới. Thấy một cô gái xinh đứng cạnh chiếc va li lớn, chẳng biết làm sao, tôi chủ động đến giúp cô khiêng nó."
