        "vi": "Không ngờ chiếc va li nặng lắm, tôi lại ngại đặt xuống nên đành gắng sức. Đi chưa xa mà đã mệt đến mồ hôi đầy đầu. Cô gái bèn bảo tôi: “Khiêng không nổi thì lăn đi.”"
