        "vi": "Vừa nghe, tôi lập tức nổi giận, đặt va li xuống rồi nhìn cô. Cô thoáng sững người, đỏ bừng mặt chỉ vào đáy va li và nói: “Em nói đến bánh xe cơ mà.”"
