        "py": "Yí ge xuésheng zhàn qǐlai wèn: “Lǎoshī, yàoshi ‘Lǚ’ zì shì jiē wěn de yìsi, nàme ‘pǐn’ zì yòu zěnme jiěshì ne? Shì sān ge rén yìqǐ jiē wěn ma?”",
        "vi": "Một sinh viên đứng dậy hỏi: “Thưa thầy, nếu chữ ‘Lữ’ nghĩa là hôn, vậy chữ ‘phẩm’ giải thích thế nào? Là ba người cùng hôn nhau ạ?”."
