        "py": "Jiàoshòu zhèng xiǎng fā huǒ, yòu yǒu yí ge xuésheng zhàn qǐlai shuō: “Wǒ kàn ‘pǐn’ zì hái hǎo jiěshì, ‘qì’ zì ne? Sì ge rén hé yì zhī gǒu zài gàn shénme ne?” Quán bān tóngxué dùnshí hāhā dà xiào qǐlai.",
        "vi": "Giáo sư vừa định nổi giận, lại có một sinh viên đứng lên nói: “Em thấy chữ ‘phẩm’ còn dễ giải thích, còn chữ ‘khí’ thì sao? Bốn người và một con chó đang làm gì ạ?”. Cả lớp lập tức phá lên cười."
