    "workbook": {
      "answerKeyNote": "Sửa câu sai\n1. 过马路时你要特别小心，千万别出事故。\n2. 我的朋友丢了钱包，我还没有丢过。\n3. 我来中国留学的目的是想亲眼看看中国的情况。\n4. 哈尔滨是中国东北的一个大城市，你应该去看看。\n5. 要是我受了伤，非哭不可。\n6. 她的记性很好，不管什么地方，只要去过一次，她就能记住。\n\nĐiền tổng hợp\n1. 坐\n2. 就\n3. 上\n4. 虽然\n5. 着\n6. 被\n7. 就",
      "exercisesNote": "Đọc hiểu tr. 15: 作者对留学的地方印象怎么样？ 她喜欢不喜欢运动？在国内她常骑车上街吗？她骑车上街时出了什么事？ 从医院出来时她的心情怎么样？ 老师为什么要她住在自己家里？ 老师怎么照顾她？ 说出或写出你来中国后遇到的一件事。\nLuyện tập tr. 21–26. Nối đoạn mục 6, đáp án 1. CBAD, 2. CABD. Mục 7 sửa câu và mục 9 điền “北国行”, đáp án tr. 196–197. Ô ④ tr. 26 có đề “忽然想④____了一句诗” nhưng phụ lục in 想. Ô này để đối chiếu ngoài phần chấm tự động.\n北国行\n元旦那天，我跟几个同学一起①____火车去哈尔滨看冰灯。刚到车站门口，②____看见很多接站的人，一出车站迎面就是几座大冰雕，像巨石一样立在广场③____。从来没有见过冰雪的我，一下子激动和兴奋起来。忽然想④____了一句诗：“北国风光，千里冰封，万里雪飘。”眼前的情景跟这句诗说的完全一样。\n第二天，我们来到了松花江上。⑤____江面上结着厚厚的冰，天很冷，但是冰上却有那么多快乐的游人。我们看到一些艺术家正在江上做冰雕，不少男女青年在自由自在地滑冰，有的人坐⑥____狗拉的大雪橇飞跑，有意思极了。我和几个朋友⑦____这一场面所吸引，也坐上大雪橇，在松花江上跑了起来。\n当然，最漂亮的还数冰灯。各种各样的颜色，各种各样的造型。走进冰灯展览厅，⑧____好像走进了一个童话世界。我无法形容它的美丽，要是你感兴趣，最好亲自去看看。"
    },
