    "workbook": {
      "answerKeyNote": "Sửa câu sai\n1. 寒假我回家看妈妈，妈妈比过去显得更老了。\n2. 我的汉语水平越来越高了。\n3. 我写我母亲，怎么写也写不完母亲的恩情。\n4. 师傅问我的时候，我没听懂。\n5. 他以前对我特别好，现在不知为什么天天对我发脾气。\n6. 他做事总是慢腾腾的，我想这就是他的性格吧，没办法。\n\nĐiền tổng hợp\n1. 了\n2. 住\n3. 为了\n4. 大家 / 人们\n5. 一下子\n6. 得\n7. 还\n8. 却\n9. 才\n10. 每当",
      "exercisesNote": "Đọc hiểu tr. 28–29: “我”开始听到别人说“慢点儿”时，是怎么想的？ “我”去清华大学做什么？路上遇到了什么麻烦？ 修车师傅为什么没有马上给“我”修车？ 修车师傅是怎么给“我”修车的？ 走出车铺，“我”心里为什么感到“暖暖的”？\nLuyện tập tr. 34–39. Mục 6 nối đoạn tr. 37, đáp án 1. CBDA, 2. BCAD. Mục 7 sửa câu tr. 37–38, mục 9 điền “从心里说一声‘对不起’” tr. 39, đáp án tr. 197.\n从心里说一声“对不起”\n记得我出国前，一位好心的朋友告诉我：“到①____国外，不要轻易说‘对不起’，要是出了交通事故或遇到什么麻烦事，你先说了‘对不起’的话，就说明你自己先承认了错误，警察一定会罚你。”我牢牢记②____了她的话。\n去年的一天，我起床晚了，可是八点钟有汉语课。③____不迟到，我加快了骑车的速度。在学校附近的十字路口，行人特别多，骑自行车的也很多，④____都争先恐后地赶着去上学、上班，路上非常拥挤。由于我骑得太快，⑤____撞到前面一辆自行车上，骑车人被我撞倒了。我也从自行车上重重地摔了下来，疼⑥____，爬不起来了。说实在的，是我撞倒了他，可是，他不仅不计较，⑦____立即爬起来扶我，并且连连说了两声“对不起！”，可是我呢，是不想说还是不敢说？总之，我撞倒了别人，⑧____没有说一声“对不起”，反而让别人对我说“对不起”。\n他把我扶起来后，问我要不要去医院看看。我对他说：“你要去上班吗？你快走吧，我没事，休息一下就好了。”，但是他不放心，就在一边陪着我，见我能推着自行车走了，他⑨____放心地跟我分手了。虽然这天我迟到了半个多小时，但是我却非常高兴。我偶然遇到的这个人，让我想了很多很多。他的心地是那么善良，又是那样宽广。⑩____想起这件事时，我就会从心里说一声：“对不起。”"
    },
