        "py": "Tā suǒ biǎolù de nà fèn shàonǚ tèyǒu de qīdài, ràng wǒ shēnshēn de gǎndòng. Wǒ zhōngyú shénme dōu méiyǒu shuō, jìxù jiāng cuò jiù cuò, ràng tā dàizhe zhè chǎng tiánmì de mèng shàng le fēijī, fēixiàng bù kě yùzhī de wèilái…",
        "vi": "Niềm mong đợi rất riêng của một thiếu nữ mà cô bộc lộ khiến tôi vô cùng xúc động. Cuối cùng tôi không nói gì, tiếp tục để sự nhầm lẫn ấy tiếp diễn, để cô mang theo giấc mơ ngọt ngào lên máy bay, bay về tương lai chưa thể biết trước…"
