    "workbook": {
      "exercisesNote": "Trả lời câu hỏi đọc hiểu (tr. 57).\n1. 这盒蛋糕是谁送给谁的？\n2. 刘西西为什么把蛋糕分给大家吃了？\n3. “我”为什么说谎？\n4. 后来“我”说出真相没有？为什么？\n5. 这场误会的结果怎样？\n6. 生活中，有时候要把真相告诉别人时可能会让别人感到尴尬，为了不让这种不愉快的情况出现，你会怎么做？\n7. 讲一个你在生活中和朋友发生“误会”的小故事。\nMục 1–2 luyện ngữ âm và cụm từ tr. 65–66. Mục 3 chọn từ tr. 66–67. Mục 4–5 hoàn thành câu và hội thoại tr. 67–68. Mục 6 nối câu tr. 68. Mục 7 sửa câu tr. 69. Mục 8 biểu đạt theo tình huống tr. 69–70. Mục 9 điền tổng hợp tr. 70.",
      "answerKeyNote": "Phụ lục tr. 198–199.\nMục 6: (1) C B A D; (2) B C A D.\nMục 7:\n1. 他比原来的老师厉害。\n2. 我本来打算从北京坐火车去香港，但是没买到票，只好坐飞机。\n3. 我们一边谈论中国社会和外国社会的不同，一边听音乐。\n4. 他已经感冒一个星期了。（你才知道。／还没好。）\n5. 我昨天晚上睡觉时梦见了她。\n6. 我起晚了，来不及吃早饭就来教室了。\nMục 9: (1) 了; (2) 李大姐; (3) 得; (4) 但是; (5) 上; (6) 给; (7) 好; (8) 过."
    },
