    "workbook": {
      "exercisesNote": "Câu hỏi đọc hiểu, tr. 73.\n1. 她为什么对人性有些失望？\n2. 她在报社做什么工作？她对自己的工作满意吗？\n3. 后来因为什么事引起了同事的不满？\n4. 她希望领导把她调离这个单位吗？\n5. 她为什么流下了感激的泪水？\n\nNgữ âm, thơ và từ ngữ tr. 79–80. Mục 3B và hoàn thành câu, tr. 80–81. Hoàn thành hội thoại và nối đoạn, tr. 81–82. Nói theo tình huống, tr. 83–84.\n\nMục 9, tr. 84. 帽子\n小丽是个可爱的小女孩，可是，当她念三年级的时候，得了一种病，必须住院接受三个月的化疗（huàliáo）。\n出院后，她显得更瘦小了，也不像以前那样活泼了。更可怕的①____，原来她有一头美丽的黑发，②____差不多都快掉光了。虽然她聪明好学，完全能补上落下的功课，然而，每天光着头到学校去上课，③____她这样一个七八岁的小女孩来说，是一件非常痛苦的事，所以她不得不戴上帽子。\n老师知道小丽的痛苦。就在她回学校上课前，对班上的孩子们说：“④____下星期一开始，我们要学习认识各种各样的帽子。所有的同学都要戴⑤____自己最喜欢的帽子到学校来，越新奇越好！”\n星期一到了，离开学校三个月的小丽第一次回到了她熟悉的教室，但是，她站在教室门口迟迟不敢进去，担心同学会笑她，因为她戴了一顶帽子。可是，让她感到意外的是，班上的每一个同学都戴⑥____帽子，和他们花花绿绿的帽子比起来，她那顶帽子显得太普通了，几乎没有引起任何人的注意。一下子，她觉得自己⑦____别人没有什么不一样，没有什么东西可以影响她与同学们自由自在地交往了，她轻松地笑了，笑得那样甜。\n日子就这样一天天过去了。现在，⑧____常常忘了自己还戴着一顶帽子；同学们好像也忘了。",
      "answerKeyNote": "Phụ lục tr. 199.\nMục 6. (1) D B A C, (2) A C B D.\nMục 7. (1) 来中国后看到中国跟我想象的不一样，感到很吃惊。／我吃了一惊。\n(2) 这次留学对我来说是很宝贵的机会。／是很难忘的经历。\n(3) 那天我请她跳了一次舞。\n(4) 我从朋友那儿知道了她的情况。\n(5) 她是美丽、大方又活泼的姑娘。\n(6) 我知道王老师和张老师是同学和朋友。\nMục 9. (1) 是, (2) 现在, (3) 对, (4) 从, (5) 上, (6) 着, (7) 跟, (8) 小丽."
    },
