        "py": "‘Nín zài shū li céng xiě dào: “Xíngwéi zhìliáo de mùdì, shì shǐ nàxiē xīnlíng tòngkǔ de rén nénggòu huídào zhèngcháng shēnghuó zhōng qù, cóng'ér xiǎngshòu zhèngchángrén dōu yōngyǒu de xìngfú hé quánlì.” Lǎoshi shuō, nín shū li de lǐlùn wǒ bìng bù dōu zànchéng, kě wǒ tóngyì zhè jù huà. Wǒ xiǎng wǒmen de fēnqí zhǐ shì zěnyàng cái néng zuò de gèng hǎo xiē, zěnyàng cái néng gèng hǎo de zhìliáo bìngrén.’",
