        "vi": "“Vậy trong khoa học, trái lòng tán thành một lý thuyết mà mình cho là sai còn khó hơn. Giả sử cậu lừa dối trong tình yêu, chỉ một người bị lừa. Nhưng nếu lừa dối trong khoa học, chỉ vì tiền mà không bảo vệ quan điểm đúng, hàng nghìn hàng vạn bệnh nhân sẽ chịu hại. Mình nghĩ nếu làm thế, lương tâm sẽ cắn rứt mình cả đời.” Cô nói “Điều quan trọng nhất với người nghiên cứu khoa học là dám giữ vững chân lý và quan điểm của mình. Dĩ nhiên, cũng phải dám sửa sai.”"
