    "workbook": {
      "exercisesNote": "Câu hỏi đọc hiểu tr. 87–88.\n1. 彭艺云为什么穿着朴素的衣服去参加面试？\n2. 她为什么和阿加尔教授争论？\n3. 她为什么希望成为阿加尔教授的研究生？\n4. 她的朋友为什么批评她？\n5. 阿加尔教授为什么要收她作自己的研究生？\n6. 用彭艺云或阿加尔的身份讲述这个故事。\n\nNgữ âm, tục ngữ và cụm từ tr. 94–95. Điền mục 3B tr. 96. Hoàn thành câu và hội thoại tr. 96–97. Nối đoạn tr. 97–98. Nói theo tình huống tr. 99.\n\nMục 9, tr. 99–100. 面试\n考试是单独面试。我一走①____小会客厅，坐在正中沙发上的一个老外便站了起来，我认②____了，他就是贝克先生，公司招聘广告上有他的照片。\n“是你？！你就是……？”贝克先生用流利的中文说出了我的名字，并且快步走到我的面前，紧紧握③____我的手。\n“原来是你！我找你找④____很长时间了。”贝克先生一脸的惊喜，激动地转过身对在座的另几位考官说道：“先生们，我给你们介绍一下，这位就是救我女儿的那位年轻人。”\n我的心狂跳起来，还没等我说话，贝克先生就把我拉到他旁边的沙发上坐下，说道：“我划船的技术太差了，不小心⑤____女儿掉进了昆明湖里，要不是你就麻烦了。真抱歉，当时我只顾看女儿了，也没来得及向你道谢。”我努力抑制住心跳，认真地说：“贝克先生，您是不是搞错了。⑥____以前从未见过您，更没救过您的女儿。”\n贝克先生又拉住我说：“你忘记了？四月二日，颐和园昆明湖上……肯定是你！我记得你脸上这颗痣。年轻人，你骗不⑦____我的。”贝克先生一脸的得意。\n我站起来：“贝克先生，我想您肯定认错人了，我真的没救过您女儿。”\n我说得很坚决，贝克先生一时愣住了。忽然，他又笑了，“年轻人，我欣赏你的诚实，好，你被录取了。”\n这时，我站⑧____说：“谢谢您的赏识。不过，对不起，我不欣赏您这样的面试，因为，这显然是在蒙人。所以，我不想到贵公司工作了。”\n说完，我走出了会客厅。",
      "answerKeyNote": "Phụ lục tr. 199–200.\nMục 6. (1) B C A D, (2) D C A B, (3) A C D B E.\nMục 7. (1) 我汉字写得马马虎虎。\n(2) 我们大家一起把圣诞树装饰一下吧。\n(3) 到晚上十二点，我还没有把功课预习完。\n(4) 我看见他们两个人骑在摩托车上……\n(5) 我们又唱歌又跳舞，玩得很高兴／尽兴。\n(6) 我今天一支烟也没有抽。\nMục 9. (1) 进, (2) 出来, (3) 住, (4) 了, (5) 把, (6) 我, (7) 了, (8) 起来."
    },
