      "头一天营业 (tr. 106). 头 đứng trước số thứ tự có nghĩa là đầu tiên. 头一天 là 第一天.",
      "把提到嗓子眼的心一下子放到了肚里 (tr. 106–107). Cách nói hài hước chỉ vừa hết lo và thấy yên tâm. 把心都提到嗓子眼儿了 diễn tả hồi hộp, lo sợ.",
      "找他们算账去 (tr. 107). 算账 nghĩa gốc là tính toán sổ sách. Trong bài khóa, nghĩa là đi tính sổ với người đã gây thiệt hại.",
      "Bài khóa được cải biên theo bài 《美丽的错误》 của 鱼在洋, như chú thích cuối tr. 103."
