      "exercisesNote": "Câu hỏi bài khóa (tr. 120).\n1. “我”的儿子怎么了？\n2. 小敏为什么落榜了？\n3. “我”怎么鼓励小敏？\n4. “我”为什么决定替儿子去听课？\n5. 几年来“我”是怎么学习的？\n6. 文学院考试那天，发生了什么事？\n\nLuyện tập tr. 127–133.\nMục 1–2: Phân biệt âm, thanh điệu, đọc câu và cụm từ (tr. 127–128).\nMục 3: Chọn từ điền trống (tr. 128–129). Mục 4–5: Hoàn thành câu và hội thoại (tr. 129–130).\nMục 6: Sắp xếp câu thành đoạn (tr. 130–131). Mục 7: Sửa câu sai (tr. 131).\nMục 8: Diễn đạt theo tình huống (tr. 131–132). Mục 9: Điền vào đoạn kể về 志强 (tr. 132–133).",
      "answerKeyNote": "Đáp án tham khảo tr. 200–201.\nMục 6: (1) C A D B; (2) B E D C A.\nMục 7:\n1. 他说：“我们一定要取得这场比赛的胜利。”\n2. 我虽然取得了一点儿成绩，但没有什么了不起的。\n3. 我已经把作业做完了。\n4. 我们用车把她送进了医院。\n5. 我虽然很努力，但是成绩仍不太好。\n6. 很多中国朋友都问我，为什么到中国来。\nMục 9: (1) 起来; (2) 就; (3) 了; (4) 怎么; (5) 都; (6) 但; (7) 回去; (8) 只要; (9) 我."
