    "workbook": {
      "exercisesNote": "Trả lời theo bài khóa (tr.135–136) — (1) 作者是从事什么工作的？ (2) 她每天怎么工作？ (3) 网络学校是怎么进行教学的？ (4) 他们的汉语远程教育怎么样？ (5) 他们为什么要举办夏令营？ (6) 夏令营准备开展哪些活动？\n1 语音 (tr.141) — Phân biệt âm, thanh điệu và đọc thành tiếng bốn câu tục ngữ. 2 词语 (tr.141–142) — Đọc các cụm từ với 信息、有关、遗憾、增进、选择.\n3 选词填空 (tr.142) — Điền 选择、遗憾、作为、有关、自豪、开办、增进、申请、按照、无数、信息、之间 vào 12 câu.\n4 完成句子 (tr.142–143) — Hoàn thành 6 câu với 只需、其中、而是、作为、既、适合. 5 完成会话 (tr.143) — Hoàn thành 6 hội thoại.\n6 连句成段 (tr.144) — Sắp xếp 2 đoạn về vai trò của mạng và tiện ích của Internet. 7 改错句 (tr.144–145) — Sửa 6 câu.\n8 情景表达 (tr.145) — Nêu hoàn cảnh cho câu bày tỏ tiếc nuối và tự hào, giải thích cách dùng máy ATM của Ngân hàng Trung Quốc, hỏi địa chỉ trang web của Nhân dân nhật báo. 9 综合填空 (tr.145) — Điền 8 chỗ trống trong đoạn về trao đổi thư điện tử với chồng đang du học.",
      "answerKeyNote": "Phụ lục tr.201, PDF 215. Bài 6: (1) C–D–B–A, (2) D–C–A–B. Bài 7: 6 câu sửa đã đưa vào câu hỏi, câu (2) có hai cách. Bài 9: ① 了, ② 为, ③ 从, ④ 成, ⑤ 了, ⑥ 上, ⑦ 到/逢, ⑧ 来."
    },
