    "workbook": {
      "answerKeyNote": "Sửa câu sai\n1. 他现在是公司里的红人。\n2. 我们都希望王老师下学期还教我们。\n3. 他说的情况是确实的，我可以证明。\n4. 家庭对孩子的影响很大。\n5. 老师讲的我都懂了，没什么疑问了。\n6. 一个有名的建筑物可以作为一个国家的象征，像天安门是中国的象征，白宫是美国的象征。\n\nĐiền tổng hợp\n1. 在\n2. 是\n3. 对\n4. 而\n5. 即使\n6. 才\n7. 对\n8. 以免",
      "exercisesNote": "Đọc hiểu tr. 164: 你同意“对颜色的好恶反映一个人性格”的观点吗？ 一般人对不同颜色会有什么样的感觉？ 不同的颜色怎样影响人的情绪？ 在汉语里，几种主要的颜色词除了本义以外，还表达什么含义？ 在你的母语里，颜色表达的意思与汉语有什么不同？\nLuyện tập tr. 172–178. Mục 6 nối đoạn tr. 175, đáp án 1. ADCEB, 2. ACBD. Mục 7 sửa câu tr. 176, mục 9 điền tổng hợp tr. 177–178, đáp án tr. 202–203."
    },
